from model import Summary


def run(data, limit):
    frames = []
    offset = 0
    while offset < len(data):
        length = data[offset]
        if length > limit:
            return Summary(frames, offset, 3)

        checksum_offset = offset + 1 + length
        if checksum_offset >= len(data):
            return Summary(frames, offset, 1)

        payload = data[offset + 1:checksum_offset]
        if data[checksum_offset] != sum(payload) % 256:
            return Summary(frames, offset, 2)

        frames.append(payload)
        offset = checksum_offset + 1

    return Summary(frames, len(data), 0)

